import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))
    groups = {}
    for i, v in enumerate(a):
        groups.setdefault(v, []).append(i)
    dist = [-1] * n
    dist[0] = 0
    dq = deque([0])
    while dq:
        i = dq.popleft()
        if i == n - 1:
            break
        d = dist[i] + 1
        if i + 1 < n and dist[i + 1] < 0:
            dist[i + 1] = d
            dq.append(i + 1)
        if i - 1 >= 0 and dist[i - 1] < 0:
            dist[i - 1] = d
            dq.append(i - 1)
        for j in groups.pop(a[i], ()):
            if dist[j] < 0:
                dist[j] = d
                dq.append(j)
    print(dist[n - 1])

